-- Aprenda se Divertindo · 110 · Simulado 2 da Trilha Saúde
-- Rode depois do 109-simulado-policial-4.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 2 da trilha Saúde: abre no sábado, 14/11/2026, às 0h, e fecha no domingo, 15/11/2026, às 23h59.
-- 80 questões de A a E, estilo AOCP, 4 horas de prova: Português 10, Raciocínio Lógico 5, Informática 5, Constitucional 2, SUS 15,
--   Enfermagem 30, Medicina 7, Fisioterapia 4, Pessoa com Deficiência 1, Igualdade Racial 1 (mesma distribuição do Simulado 1).
-- Gabarito equilibrado: 16 questões com cada letra (A a E), sem três letras iguais seguidas.
-- Gabarito comentado liberado na segunda, 16/11, às 0h. Rodar de novo atualiza as questões, desde que ninguém tenha começado.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Na sala de espera de uma unidade básica de saúde, o tempo parece ter outro ritmo. Ali se encontram a gestante que vem para o pré-natal, o idoso que renova a receita do remédio de pressão, a mãe que traz a criança para a vacina. À primeira vista, nada de extraordinário acontece. No entanto, é nesse cotidiano discreto que se evita boa parte das internações que lotam os hospitais.\n\nA atenção primária costuma ser lembrada como a porta de entrada do sistema, mas a imagem é incompleta. Uma porta apenas dá passagem; a atenção primária, ao contrário, acompanha. Conhece a família pelo nome, sabe quem deixou de buscar a medicação, percebe quando a criança não voltou para a consulta. Esse vínculo, construído ao longo do tempo, é justamente o que permite agir antes que a doença se agrave. Quando ele se rompe, o paciente só reaparece na emergência — e, então, quase sempre tarde.", "enunciado": "Segundo o texto, a imagem da atenção primária como “porta de entrada” do sistema é incompleta porque", "opcoes": ["o acesso às unidades básicas depende de encaminhamento.", "a verdadeira porta de entrada do sistema é a emergência.", "a atenção primária também acompanha o paciente ao longo do tempo.", "a maioria dos pacientes procura primeiro os hospitais.", "as unidades básicas atendem apenas os casos de baixa gravidade clínica."], "gabarito": 2, "explicacao": "O autor diz que uma porta apenas dá passagem, enquanto a atenção primária “acompanha”: conhece a família, percebe faltas e age antes que a doença se agrave."}, {"materia": "port", "texto_base": "Na sala de espera de uma unidade básica de saúde, o tempo parece ter outro ritmo. Ali se encontram a gestante que vem para o pré-natal, o idoso que renova a receita do remédio de pressão, a mãe que traz a criança para a vacina. À primeira vista, nada de extraordinário acontece. No entanto, é nesse cotidiano discreto que se evita boa parte das internações que lotam os hospitais.\n\nA atenção primária costuma ser lembrada como a porta de entrada do sistema, mas a imagem é incompleta. Uma porta apenas dá passagem; a atenção primária, ao contrário, acompanha. Conhece a família pelo nome, sabe quem deixou de buscar a medicação, percebe quando a criança não voltou para a consulta. Esse vínculo, construído ao longo do tempo, é justamente o que permite agir antes que a doença se agrave. Quando ele se rompe, o paciente só reaparece na emergência — e, então, quase sempre tarde.", "enunciado": "No primeiro parágrafo, a expressão “No entanto” estabelece relação de", "opcoes": ["explicação, detalhando quem são as pessoas que aguardam na sala de espera.", "oposição entre a aparência banal da cena e a importância do trabalho.", "causa, explicando por que os hospitais estão lotados.", "conclusão, resumindo as situações descritas na sala de espera.", "adição, acrescentando um novo exemplo de paciente atendido."], "gabarito": 1, "explicacao": "“No entanto” é conjunção adversativa. Contrapõe o “nada de extraordinário acontece” ao fato de que ali se evitam muitas internações."}, {"materia": "port", "texto_base": "Na sala de espera de uma unidade básica de saúde, o tempo parece ter outro ritmo. Ali se encontram a gestante que vem para o pré-natal, o idoso que renova a receita do remédio de pressão, a mãe que traz a criança para a vacina. À primeira vista, nada de extraordinário acontece. No entanto, é nesse cotidiano discreto que se evita boa parte das internações que lotam os hospitais.\n\nA atenção primária costuma ser lembrada como a porta de entrada do sistema, mas a imagem é incompleta. Uma porta apenas dá passagem; a atenção primária, ao contrário, acompanha. Conhece a família pelo nome, sabe quem deixou de buscar a medicação, percebe quando a criança não voltou para a consulta. Esse vínculo, construído ao longo do tempo, é justamente o que permite agir antes que a doença se agrave. Quando ele se rompe, o paciente só reaparece na emergência — e, então, quase sempre tarde.", "enunciado": "O travessão em “— e, então, quase sempre tarde” foi empregado para", "opcoes": ["destacar a consequência negativa do rompimento do vínculo.", "introduzir a fala de um profissional de saúde.", "isolar uma explicação sobre o funcionamento da emergência.", "indicar uma ressalva que contradiz a frase anterior.", "marcar a enumeração de pacientes atendidos na unidade."], "gabarito": 0, "explicacao": "O travessão dá ênfase ao desfecho: sem o vínculo, o paciente só volta na emergência, quando a doença já se agravou."}, {"materia": "port", "texto_base": "Na sala de espera de uma unidade básica de saúde, o tempo parece ter outro ritmo. Ali se encontram a gestante que vem para o pré-natal, o idoso que renova a receita do remédio de pressão, a mãe que traz a criança para a vacina. À primeira vista, nada de extraordinário acontece. No entanto, é nesse cotidiano discreto que se evita boa parte das internações que lotam os hospitais.\n\nA atenção primária costuma ser lembrada como a porta de entrada do sistema, mas a imagem é incompleta. Uma porta apenas dá passagem; a atenção primária, ao contrário, acompanha. Conhece a família pelo nome, sabe quem deixou de buscar a medicação, percebe quando a criança não voltou para a consulta. Esse vínculo, construído ao longo do tempo, é justamente o que permite agir antes que a doença se agrave. Quando ele se rompe, o paciente só reaparece na emergência — e, então, quase sempre tarde.", "enunciado": "Em “Esse vínculo, construído ao longo do tempo, é justamente o que permite agir”, a expressão “Esse vínculo” retoma", "opcoes": ["a receita de remédio renovada pelo idoso.", "o tempo de espera dos pacientes na recepção da unidade de saúde.", "a imagem da porta de entrada do sistema de saúde.", "a passagem do paciente pela emergência do hospital.", "a relação de acompanhamento entre a equipe e as famílias."], "gabarito": 4, "explicacao": "O pronome “esse” retoma o que foi dito antes: conhecer a família pelo nome, saber quem deixou de buscar a medicação, perceber faltas. Isso é o vínculo de acompanhamento."}, {"materia": "port", "texto_base": "Na sala de espera de uma unidade básica de saúde, o tempo parece ter outro ritmo. Ali se encontram a gestante que vem para o pré-natal, o idoso que renova a receita do remédio de pressão, a mãe que traz a criança para a vacina. À primeira vista, nada de extraordinário acontece. No entanto, é nesse cotidiano discreto que se evita boa parte das internações que lotam os hospitais.\n\nA atenção primária costuma ser lembrada como a porta de entrada do sistema, mas a imagem é incompleta. Uma porta apenas dá passagem; a atenção primária, ao contrário, acompanha. Conhece a família pelo nome, sabe quem deixou de buscar a medicação, percebe quando a criança não voltou para a consulta. Esse vínculo, construído ao longo do tempo, é justamente o que permite agir antes que a doença se agrave. Quando ele se rompe, o paciente só reaparece na emergência — e, então, quase sempre tarde.", "enunciado": "Em “a imagem é incompleta”, a palavra “incompleta” pode ser substituída, sem prejuízo do sentido do texto, por", "opcoes": ["falsa.", "ofensiva.", "ultrapassada.", "exagerada.", "parcial."], "gabarito": 4, "explicacao": "O autor não diz que a imagem é falsa, mas que não mostra tudo: ela é parcial, pois a atenção primária dá passagem e também acompanha."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o acento indicativo de crase está empregado corretamente.", "opcoes": ["A vacina deve ser aplicada à partir dos seis meses de idade.", "A equipe ficou cara à cara com um surto de sarampo.", "Os curativos devem ser trocados à cada 12 horas.", "A enfermeira entregou o relatório à coordenadora da unidade.", "O paciente foi encaminhado à um especialista."], "gabarito": 3, "explicacao": "“Entregar algo a alguém” + “a coordenadora” = “à coordenadora”. Não há crase antes de artigo indefinido (a um), antes de verbo (a partir), antes de “cada” nem entre palavras repetidas (cara a cara)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à concordância nominal.", "opcoes": ["As técnicas ficaram meias cansadas após o plantão.", "Seguem anexo os exames solicitados pelo médico.", "Havia bastante pacientes aguardando na recepção.", "É proibida a entrada de acompanhantes na sala de vacina.", "A própria enfermeira avisou aos pacientes: “Eu mesmo aplico a vacina”."], "gabarito": 3, "explicacao": "Com o artigo (“a entrada”), o adjetivo concorda: “é proibida”. O correto nas demais é: seguem anexos os exames, eu mesma (falante mulher), bastantes pacientes (adjetivo, varia) e meio cansadas (advérbio, invariável)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa correta quanto ao emprego do pronome relativo.", "opcoes": ["O medicamento de que o médico prescreveu acabou na farmácia.", "O hospital cujos os leitos foram ampliados atende toda a região.", "A unidade onde o médico se referiu fica no centro da cidade.", "A paciente que o filho foi internado aguarda na recepção.", "O hospital cujos leitos foram ampliados atende toda a região."], "gabarito": 4, "explicacao": "“Cujo” indica posse e não admite artigo depois dele. O correto nas demais é: a paciente cujo filho foi internado, a unidade a que o médico se referiu e o medicamento que o médico prescreveu (prescrever é transitivo direto)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que todas as palavras estão grafadas corretamente.", "opcoes": ["exceção – análise – privilégio", "exceção – análise – previlégio", "exceção – análize – privilégio", "esceção – analise – privilégio", "excessão – análise – privilégio"], "gabarito": 0, "explicacao": "A grafia correta é exceção (com “ç”), análise (com “s” e acento) e privilégio (com “i” na primeira sílaba)."}, {"materia": "port", "texto_base": "", "enunciado": "Transpondo-se a frase “Os técnicos aplicaram as vacinas” para a voz passiva analítica, obtém-se:", "opcoes": ["As vacinas tinham sido aplicadas pelos técnicos.", "Os técnicos tinham aplicado as vacinas.", "As vacinas eram aplicadas pelos técnicos.", "Aplicaram-se as vacinas pelos técnicos.", "As vacinas foram aplicadas pelos técnicos."], "gabarito": 4, "explicacao": "O verbo “aplicaram” está no pretérito perfeito. Na voz passiva analítica, usa-se “ser” no mesmo tempo mais o particípio: foram aplicadas. “Eram” e “tinham sido” mudam o tempo verbal."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “Se o paciente tem febre, então ele toma antitérmico” é:", "opcoes": ["Se o paciente não tem febre, então não toma antitérmico.", "Se o paciente toma antitérmico, então tem febre.", "O paciente tem febre e não toma antitérmico.", "O paciente não tem febre e toma antitérmico.", "O paciente não tem febre ou toma antitérmico."], "gabarito": 2, "explicacao": "A negação de “se p, então q” é “p e não q”: a febre acontece e o antitérmico não é tomado. “Não p ou q” é equivalente à própria condicional."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma unidade de saúde recebeu 240 doses de vacina e aplicou 35% delas na primeira semana. O número de doses que ainda restam é", "opcoes": ["205.", "140.", "84.", "156.", "165."], "gabarito": 3, "explicacao": "35% de 240 = 0,35 · 240 = 84 doses aplicadas. Restam 240 − 84 = 156 doses."}, {"materia": "rl", "texto_base": "", "enunciado": "Três enfermeiros fazem 60 curativos em 4 horas. Mantido o mesmo ritmo de trabalho, cinco enfermeiros farão, em 6 horas,", "opcoes": ["150 curativos.", "120 curativos.", "100 curativos.", "200 curativos.", "90 curativos."], "gabarito": 0, "explicacao": "Cada enfermeiro faz 60 / (3 · 4) = 5 curativos por hora. Cinco enfermeiros em 6 horas: 5 · 6 · 5 = 150."}, {"materia": "rl", "texto_base": "", "enunciado": "Em um hospital, 50 profissionais foram consultados: 30 fazem plantão diurno, 25 fazem plantão noturno e 8 não fazem plantão. O número de profissionais que fazem os dois tipos de plantão é", "opcoes": ["17.", "13.", "8.", "5.", "12."], "gabarito": 1, "explicacao": "Fazem algum plantão 50 − 8 = 42 profissionais. Pela fórmula da união: 30 + 25 − x = 42, então x = 13."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma proposição equivalente a “Não é verdade que Ana é médica ou enfermeira” é:", "opcoes": ["Ana não é médica ou não é enfermeira.", "Ana não é médica e não é enfermeira.", "Se Ana não é médica, então é enfermeira.", "Ana é médica e enfermeira.", "Ana é médica ou não é enfermeira."], "gabarito": 1, "explicacao": "Pela lei de De Morgan, negar “p ou q” resulta em “não p e não q”: Ana não é nenhuma das duas coisas."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Excel, a célula A1 contém o valor 6,5. A fórmula =SE(A1>=7;\"Apto\";\"Inapto\") retorna", "opcoes": ["o erro #VALOR!.", "6,5.", "VERDADEIRO.", "Apto.", "Inapto."], "gabarito": 4, "explicacao": "A função SE testa a condição A1 >= 7. Como 6,5 é menor que 7, a condição é falsa e a fórmula retorna o terceiro argumento, “Inapto”."}, {"materia": "inf", "texto_base": "", "enunciado": "Ao entrar em seu e-mail, o usuário digita a senha e, em seguida, um código enviado ao celular. Esse mecanismo de segurança é chamado de", "opcoes": ["autenticação em dois fatores.", "criptografia de ponta a ponta.", "certificado digital do navegador.", "firewall pessoal.", "backup incremental."], "gabarito": 0, "explicacao": "A autenticação em dois fatores combina algo que o usuário sabe (a senha) com algo que ele possui (o celular). Assim, a senha vazada sozinha não basta para invadir a conta."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows 10 e 11, o atalho de teclado Windows + L serve para", "opcoes": ["desligar o computador imediatamente.", "bloquear a sessão do usuário, exigindo senha para voltar.", "abrir o Explorador de Arquivos.", "abrir as configurações de idioma.", "minimizar todas as janelas abertas."], "gabarito": 1, "explicacao": "Windows + L bloqueia a tela. É o atalho indicado quando o profissional se afasta do computador com prontuários abertos. Windows + E abre o Explorador e Windows + D mostra a área de trabalho."}, {"materia": "inf", "texto_base": "", "enunciado": "Uma clínica passa a guardar seus documentos em servidores de uma empresa, acessados pela internet de qualquer lugar. Esse modelo é chamado de", "opcoes": ["computação em nuvem.", "computação embarcada.", "armazenamento em mídia removível.", "intranet.", "rede local cabeada."], "gabarito": 0, "explicacao": "Na computação em nuvem, dados e programas ficam em servidores remotos e são acessados pela internet, sem depender de um computador específico."}, {"materia": "inf", "texto_base": "", "enunciado": "Pela Lei Geral de Proteção de Dados (Lei 13.709/2018), as informações sobre a saúde de um paciente são classificadas como", "opcoes": ["dados públicos de livre acesso.", "dados pessoais comuns, sem proteção especial.", "dados pessoais sensíveis.", "metadados institucionais.", "dados anonimizados."], "gabarito": 2, "explicacao": "A LGPD (art. 5º, II) inclui o dado referente à saúde entre os dados pessoais sensíveis, que recebem proteção reforçada."}, {"materia": "const", "texto_base": "", "enunciado": "Pelo art. 197 da Constituição Federal, as ações e os serviços de saúde são de relevância pública, e sua execução deve ser feita", "opcoes": ["exclusivamente por servidores públicos efetivos, aprovados em concurso público.", "diretamente pelo Poder Público ou por terceiros, inclusive do setor privado.", "exclusivamente por empresas privadas contratadas.", "somente por entidades filantrópicas conveniadas.", "apenas pelos municípios, vedada a atuação da União."], "gabarito": 1, "explicacao": "O art. 197 diz que as ações e os serviços de saúde são de relevância pública, cabendo ao Poder Público regulamentá-los, fiscalizá-los e controlá-los. A execução pode ser direta ou por terceiros, inclusive pessoa física ou jurídica de direito privado."}, {"materia": "const", "texto_base": "", "enunciado": "Entre as competências que o art. 200 da Constituição Federal atribui ao Sistema Único de Saúde está", "opcoes": ["administrar os planos de saúde privados.", "legislar sobre direito penal sanitário.", "conceder aposentadoria por invalidez aos trabalhadores afastados por doença ocupacional.", "executar o policiamento ostensivo das vigilâncias.", "colaborar na proteção do meio ambiente, nele compreendido o do trabalho."], "gabarito": 4, "explicacao": "O art. 200 lista, entre outras competências do SUS, executar ações de vigilância sanitária, epidemiológica e de saúde do trabalhador, fiscalizar alimentos e colaborar na proteção do meio ambiente, nele compreendido o do trabalho."}, {"materia": "sus", "texto_base": "", "enunciado": "Uma pessoa sem carteira assinada e sem plano de saúde procura atendimento em um hospital público e é atendida normalmente. Esse atendimento concretiza o princípio do SUS da", "opcoes": ["regionalização, que limita o atendimento ao município de residência do paciente.", "hierarquização, que exige encaminhamento da unidade básica.", "contributividade, pois o atendimento é custeado pelo INSS.", "equidade, que garante atendimento só a quem não pode pagar.", "universalidade de acesso aos serviços de saúde em todos os níveis."], "gabarito": 4, "explicacao": "A universalidade (art. 7º, I, da Lei 8.080/1990) garante acesso a todos, independentemente de contribuição, renda ou vínculo de emprego."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.080/1990, a integralidade de assistência é entendida como", "opcoes": ["o atendimento de todos os brasileiros e estrangeiros residentes, sem qualquer tipo de distinção.", "a oferta de serviços apenas no nível de atenção mais complexo.", "a distribuição dos serviços entre União, estados e municípios.", "o conjunto articulado e contínuo de ações preventivas e curativas, individuais e coletivas.", "a participação da comunidade nos conselhos de saúde."], "gabarito": 3, "explicacao": "O art. 7º, II, define integralidade como conjunto articulado e contínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.142/1990, a Conferência de Saúde reúne-se para avaliar a situação de saúde e propor diretrizes para a formulação da política de saúde", "opcoes": ["a cada 4 anos.", "anualmente.", "a cada 5 anos.", "mensalmente.", "a cada 2 anos."], "gabarito": 0, "explicacao": "O art. 1º, § 1º, da Lei 8.142/1990 prevê que a Conferência de Saúde se reúne a cada quatro anos, com a representação dos vários segmentos sociais."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.142/1990, o Conselho de Saúde, composto por representantes do governo, prestadores de serviço, profissionais de saúde e usuários, tem caráter", "opcoes": ["fiscalizador, sem poder de deliberação.", "permanente e deliberativo.", "eventual, reunindo-se a cada 4 anos.", "permanente e apenas consultivo.", "temporário e consultivo."], "gabarito": 1, "explicacao": "O art. 1º, § 2º, da Lei 8.142/1990 diz que o Conselho de Saúde tem caráter permanente e deliberativo e atua na formulação de estratégias e no controle da execução da política de saúde. Quem se reúne a cada 4 anos é a Conferência."}, {"materia": "sus", "texto_base": "", "enunciado": "Uma equipe inspeciona uma farmácia, verifica a validade dos medicamentos e interdita produtos vencidos. Pela Lei 8.080/1990, essa ação é de", "opcoes": ["saúde do trabalhador.", "vigilância epidemiológica.", "vigilância nutricional.", "vigilância sanitária.", "assistência terapêutica integral."], "gabarito": 3, "explicacao": "Vigilância sanitária é o conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde e intervir nos problemas sanitários do meio ambiente, da produção e circulação de bens e da prestação de serviços (art. 6º, § 1º)."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.080/1990, a direção do SUS é única em cada esfera de governo, sendo exercida, no âmbito dos estados, pela", "opcoes": ["Comissão Intergestores Bipartite.", "Conselho Estadual de Saúde.", "Assembleia Legislativa.", "Secretaria de Saúde ou órgão equivalente.", "Agência Nacional de Vigilância Sanitária."], "gabarito": 3, "explicacao": "O art. 9º atribui a direção ao Ministério da Saúde na União, às secretarias de saúde (ou órgãos equivalentes) nos estados, DF e municípios."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.080/1990, são determinantes e condicionantes da saúde, entre outros,", "opcoes": ["alimentação, moradia, saneamento básico, trabalho, renda, educação e lazer.", "o número de hospitais e de médicos por habitante, apenas, segundo os indicadores oficiais.", "apenas a oferta de consultas, exames e medicamentos.", "a existência de plano de saúde privado e de previdência.", "somente a herança genética e a idade do indivíduo."], "gabarito": 0, "explicacao": "O art. 3º cita alimentação, moradia, saneamento básico, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso aos bens e serviços essenciais."}, {"materia": "sus", "texto_base": "", "enunciado": "Pelo Decreto 7.508/2011, para ser instituída, a Região de Saúde deve conter, no mínimo, ações e serviços de", "opcoes": ["atenção primária, urgência e emergência, psicossocial, especializada, hospitalar e vigilância em saúde.", "atenção primária e vigilância em saúde, apenas.", "atenção psicossocial e assistência farmacêutica, apenas, conforme a pactuação feita na comissão intergestores.", "urgência e emergência, exclusivamente.", "atenção hospitalar de alta complexidade e transplantes."], "gabarito": 0, "explicacao": "O art. 5º do decreto exige, no mínimo: atenção primária, urgência e emergência, atenção psicossocial, atenção ambulatorial especializada e hospitalar, e vigilância em saúde."}, {"materia": "sus", "texto_base": "", "enunciado": "Pelo Decreto 7.508/2011, o acordo de colaboração firmado entre entes federativos para organizar e integrar as ações e serviços de saúde na rede regionalizada e hierarquizada é o", "opcoes": ["Relatório Anual de Gestão.", "Contrato Organizativo da Ação Pública da Saúde (COAP).", "Mapa da Saúde.", "Plano Diretor de Regionalização e Investimentos (PDRI).", "Termo de Compromisso de Gestão."], "gabarito": 1, "explicacao": "O art. 2º, II, do decreto define o COAP como esse acordo de colaboração, com responsabilidades, indicadores, metas, recursos e formas de controle."}, {"materia": "sus", "texto_base": "", "enunciado": "A Comissão Intergestores Bipartite (CIB), instância de pactuação do SUS, é formada por representantes", "opcoes": ["dos usuários e dos trabalhadores de saúde.", "do estado e dos municípios.", "dos municípios de uma mesma região de saúde, apenas.", "da União, dos estados e dos municípios.", "da União e dos estados."], "gabarito": 1, "explicacao": "A CIB reúne gestores do estado e dos municípios, no âmbito estadual. A CIT reúne União, estados e municípios, e a CIR atua na região de saúde."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Política Nacional de Atenção Básica (PNAB, 2017), a equipe de Saúde da Família deve ser composta, no mínimo, por", "opcoes": ["médico e técnico de enfermagem, apenas.", "médico, enfermeiro, dentista, farmacêutico e agente comunitário de saúde, obrigatoriamente.", "médico, psicólogo, assistente social e nutricionista.", "enfermeiro e agentes comunitários de saúde, apenas.", "médico, enfermeiro, auxiliar ou técnico de enfermagem e agente comunitário de saúde."], "gabarito": 4, "explicacao": "A PNAB 2017 define a equipe mínima da Saúde da Família: médico, enfermeiro, auxiliar e/ou técnico de enfermagem e agente comunitário de saúde. A saúde bucal pode ser acrescentada."}, {"materia": "sus", "texto_base": "", "enunciado": "A equipe de uma unidade básica acompanha a mesma família por anos, conhece sua história e mantém o vínculo ao longo do tempo. Essa diretriz da Atenção Básica é chamada de", "opcoes": ["territorialização.", "coordenação do cuidado em rede.", "longitudinalidade do cuidado.", "ordenação da rede.", "resolutividade."], "gabarito": 2, "explicacao": "Longitudinalidade é a continuidade da relação de cuidado, com vínculo e responsabilização entre profissionais e usuários ao longo do tempo (PNAB 2017)."}, {"materia": "sus", "texto_base": "", "enunciado": "Pelas normas do Ministério da Saúde, a notificação compulsória imediata de uma doença ou agravo deve ser feita em até", "opcoes": ["48 horas, contadas a partir da confirmação laboratorial do caso.", "7 dias, a partir do conhecimento da ocorrência.", "30 dias, no relatório mensal da unidade.", "72 horas, após o óbito do paciente.", "24 horas, a partir do conhecimento da ocorrência."], "gabarito": 4, "explicacao": "A notificação imediata deve ser feita em até 24 horas do conhecimento do caso, pelo meio mais rápido disponível. A notificação semanal é feita em até 7 dias."}, {"materia": "sus", "texto_base": "", "enunciado": "Na Política Nacional de Humanização (HumanizaSUS), a diretriz que reorganiza a recepção para escutar o usuário e priorizar o atendimento conforme a gravidade, e não pela ordem de chegada, é o", "opcoes": ["acolhimento com classificação de risco.", "prontuário transdisciplinar.", "apoio matricial.", "projeto terapêutico singular (PTS) da equipe.", "colegiado gestor."], "gabarito": 0, "explicacao": "O acolhimento com classificação de risco organiza o atendimento pela gravidade e pela necessidade de cada usuário, e não pela ordem de chegada."}, {"materia": "sus", "texto_base": "", "enunciado": "Pela Lei 8.142/1990, para receber os recursos do Fundo Nacional de Saúde, os municípios devem contar, entre outros requisitos, com", "opcoes": ["laboratório central de saúde pública.", "Fundo de Saúde, Conselho de Saúde, plano de saúde e relatório de gestão.", "faculdade de medicina conveniada.", "plano de saúde privado contratado para todos os servidores municipais.", "hospital próprio de alta complexidade."], "gabarito": 1, "explicacao": "O art. 4º exige Fundo de Saúde, Conselho de Saúde, plano de saúde, relatórios de gestão, contrapartida de recursos no orçamento e comissão para elaborar o plano de carreira."}, {"materia": "enf", "texto_base": "", "enunciado": "Pela Lei 7.498/1986, cabe ao técnico de enfermagem, entre outras atividades,", "opcoes": ["fazer a prescrição da assistência de enfermagem.", "realizar a consulta de enfermagem.", "prestar, como atividade privativa, os cuidados de maior complexidade técnica a pacientes graves.", "dirigir o serviço de enfermagem da instituição.", "participar da orientação e supervisão do trabalho de enfermagem em grau auxiliar."], "gabarito": 4, "explicacao": "O art. 12 atribui ao técnico atividade de nível médio, como participar da orientação e supervisão do trabalho de enfermagem em grau auxiliar. Consulta, prescrição, direção do serviço e cuidados de maior complexidade são privativos do enfermeiro."}, {"materia": "enf", "texto_base": "", "enunciado": "No processo de enfermagem, é privativo do enfermeiro", "opcoes": ["estabelecer o diagnóstico e a prescrição de enfermagem.", "registrar a anotação dos cuidados prestados durante todo o plantão.", "aferir e registrar os sinais vitais.", "executar os cuidados prescritos.", "comunicar intercorrências à equipe."], "gabarito": 0, "explicacao": "As resoluções do Cofen sobre o processo de enfermagem reservam ao enfermeiro o diagnóstico e a prescrição de enfermagem. Técnicos e auxiliares participam da execução e das anotações."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente com pneumonia, respirando em ar ambiente, apresenta saturação de oxigênio (SpO₂) de 88% na oximetria de pulso. Esse achado indica", "opcoes": ["erro do aparelho, pois esse valor é incompatível com a vida.", "hipercapnia confirmada, sem necessidade de outra avaliação.", "hiperóxia, pelo excesso de oxigênio no sangue.", "valor normal para um adulto em repouso.", "hipoxemia, que exige avaliação para oxigenoterapia."], "gabarito": 4, "explicacao": "Em adultos sem doença pulmonar crônica, espera-se SpO₂ em torno de 95% ou mais. Valor de 88% em ar ambiente indica hipoxemia. A oximetria não mede o gás carbônico, então não confirma hipercapnia."}, {"materia": "enf", "texto_base": "", "enunciado": "Na aferição da pressão arterial pelo método auscultatório, é conduta correta", "opcoes": ["usar sempre o mesmo manguito padrão, qualquer que seja a circunferência do braço do paciente.", "posicionar o manguito 2 a 3 cm acima da fossa cubital, com o braço na altura do coração.", "aferir logo após o paciente subir escadas, para avaliar o esforço.", "manter o braço do paciente pendente, abaixo do nível do coração.", "posicionar o estetoscópio sob o manguito, bem apertado."], "gabarito": 1, "explicacao": "O manguito deve ficar 2 a 3 cm acima da fossa cubital, com o braço apoiado na altura do coração e o paciente em repouso. O tamanho do manguito deve ser adequado à circunferência do braço."}, {"materia": "enf", "texto_base": "", "enunciado": "Foi prescrito soro fisiológico 0,9%, 500 mL, para correr em 8 horas, em equipo de macrogotas. O gotejamento deve ser de aproximadamente", "opcoes": ["7 gotas por minuto.", "63 gotas por minuto.", "21 gotas por minuto.", "28 gotas por minuto.", "42 gotas por minuto."], "gabarito": 2, "explicacao": "Macrogotas: gotas/min = volume / (tempo em horas × 3) = 500 / (8 × 3) = 500 / 24 ≈ 20,8, ou seja, cerca de 21 gotas por minuto."}, {"materia": "enf", "texto_base": "", "enunciado": "Um soro de 1.000 mL está correndo a 25 gotas por minuto, em equipo de macrogotas. O tempo total de infusão será de aproximadamente", "opcoes": ["12 horas e 30 minutos.", "8 horas.", "10 horas.", "40 horas.", "13 horas e 20 minutos."], "gabarito": 4, "explicacao": "Tempo (h) = volume / (gotas/min × 3) = 1.000 / 75 ≈ 13,33 horas, ou seja, 13 horas e 20 minutos."}, {"materia": "enf", "texto_base": "", "enunciado": "A quantidade de glicose contida em um frasco de 500 mL de soro glicosado a 5% é de", "opcoes": ["2,5 g.", "100 g.", "25 g.", "5 g.", "50 g."], "gabarito": 2, "explicacao": "A solução a 5% tem 5 g em cada 100 mL. Em 500 mL: 5 × 5 = 25 g de glicose."}, {"materia": "enf", "texto_base": "", "enunciado": "Foram prescritas 5.000 UI de heparina por via subcutânea. O frasco disponível contém 25.000 UI em 5 mL. O volume a ser aspirado é de", "opcoes": ["2 mL.", "1 mL.", "0,2 mL.", "0,5 mL.", "5 mL."], "gabarito": 1, "explicacao": "25.000 UI / 5 mL = 5.000 UI por mL. Para 5.000 UI, aspira-se 1 mL."}, {"materia": "enf", "texto_base": "", "enunciado": "Na aplicação de insulina por via subcutânea, é recomendado", "opcoes": ["aplicar no músculo deltoide, com ângulo de 15°.", "massagear vigorosamente o local logo após a injeção.", "fazer rodízio dos locais de aplicação, para prevenir lipodistrofia.", "aplicar sempre no mesmo ponto, para facilitar a absorção.", "usar a via intramuscular quando a glicemia estiver alta, por rotina."], "gabarito": 2, "explicacao": "O rodízio dos locais (abdome, braços, coxas, nádegas) evita a lipodistrofia, que prejudica a absorção da insulina. Não se massageia o local, e a via de rotina é a subcutânea."}, {"materia": "enf", "texto_base": "", "enunciado": "A prova tuberculínica e a vacina BCG são administradas por via intradérmica. O ângulo de introdução da agulha nessa via é de aproximadamente", "opcoes": ["15°.", "60°.", "45°.", "90°.", "30°, com o bisel voltado para baixo."], "gabarito": 0, "explicacao": "Na via intradérmica, a agulha é introduzida quase paralela à pele, em ângulo de cerca de 15°, com o bisel para cima, formando uma pápula. Subcutânea usa 45° ou 90°, e intramuscular, 90°."}, {"materia": "enf", "texto_base": "", "enunciado": "A vacina BCG deve ser aplicada por via intradérmica, preferencialmente", "opcoes": ["no braço esquerdo, no terço médio do músculo deltoide, após antissepsia com álcool.", "na região glútea.", "na face anterolateral da coxa direita.", "no antebraço esquerdo, na face interna.", "no braço direito, na inserção inferior do músculo deltoide."], "gabarito": 4, "explicacao": "Pela norma do Ministério da Saúde, a BCG é aplicada no braço direito, na altura da inserção inferior do deltoide. A padronização facilita identificar a cicatriz vacinal."}, {"materia": "enf", "texto_base": "", "enunciado": "Segundo o Programa Nacional de Imunizações, a primeira dose da vacina hepatite B deve ser aplicada no recém-nascido", "opcoes": ["aos 2 meses de vida, junto com a primeira dose da vacina pentavalente.", "somente após o teste do pezinho.", "apenas se a mãe tiver sorologia positiva.", "nas primeiras 24 horas de vida, de preferência nas primeiras 12 horas.", "aos 30 dias de vida, na primeira consulta."], "gabarito": 3, "explicacao": "A dose ao nascer deve ser dada o mais cedo possível, nas primeiras 24 horas e de preferência nas primeiras 12 horas, ainda na maternidade. Isso previne a transmissão vertical."}, {"materia": "enf", "texto_base": "", "enunciado": "Pelo Calendário Nacional de Vacinação, a primeira dose da vacina tríplice viral (sarampo, caxumba e rubéola) é aplicada na criança aos", "opcoes": ["4 anos de idade.", "9 meses de idade.", "2 meses de idade.", "12 meses de idade.", "6 meses de idade."], "gabarito": 3, "explicacao": "No calendário de rotina, a tríplice viral é dada aos 12 meses. Aos 15 meses vem a dose com tetraviral (ou tríplice viral e varicela)."}, {"materia": "enf", "texto_base": "", "enunciado": "Segundo a Anvisa, a fricção antisséptica das mãos com preparação alcoólica deve durar", "opcoes": ["de 20 a 30 segundos.", "de 2 a 3 minutos.", "de 5 a 10 segundos.", "cerca de 1 minuto e meio.", "de 40 a 60 segundos."], "gabarito": 0, "explicacao": "Com preparação alcoólica, a fricção dura de 20 a 30 segundos. A higienização com água e sabonete leva de 40 a 60 segundos."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente com suspeita de meningite meningocócica é internado. Até completar 24 horas de antibiótico eficaz, a precaução indicada é a precaução", "opcoes": ["padrão, sem nenhuma medida adicional.", "para aerossóis, com máscara PFF2 e quarto com pressão negativa durante toda a internação.", "para gotículas, com máscara cirúrgica para quem se aproximar do paciente.", "reversa, para proteger o paciente de infecções.", "de contato, apenas com luvas."], "gabarito": 2, "explicacao": "A doença meningocócica se transmite por gotículas respiratórias. Usa-se máscara cirúrgica a menos de 1 metro do paciente, de preferência em quarto privativo, até 24 horas de tratamento eficaz."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente colonizado por bactéria multirresistente (como a KPC) está internado. Além das precauções padrão, a equipe deve adotar precauções", "opcoes": ["para aerossóis, com máscara PFF2.", "nenhuma adicional, apenas higiene das mãos.", "para gotículas, com máscara cirúrgica.", "de contato, com uso de luvas e avental.", "reversas, com isolamento protetor."], "gabarito": 3, "explicacao": "Micro-organismos multirresistentes se transmitem principalmente por contato direto e indireto. Por isso se usam luvas e avental, além da higiene das mãos."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente acamado apresenta lesão sacral com perda total da espessura da pele e tecido adiposo visível, sem exposição de fáscia, músculo ou osso. Pela classificação da NPIAP, trata-se de lesão por pressão", "opcoes": ["estágio 3.", "estágio 2.", "estágio 4.", "não classificável.", "estágio 1."], "gabarito": 0, "explicacao": "No estágio 3 há perda total da espessura da pele com gordura visível. No estágio 2, a perda é parcial e expõe a derme. No estágio 4, há exposição de fáscia, músculo, tendão ou osso."}, {"materia": "enf", "texto_base": "", "enunciado": "Na admissão hospitalar de um idoso, a enfermeira aplica a Escala de Morse. Essa escala é usada para avaliar o risco de", "opcoes": ["flebite.", "broncoaspiração.", "desnutrição.", "queda.", "lesão por pressão."], "gabarito": 3, "explicacao": "A Escala de Morse avalia o risco de queda: histórico de quedas, diagnóstico secundário, auxílio na deambulação, terapia endovenosa, marcha e estado mental. Para lesão por pressão usa-se a Braden."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente vítima de trauma abre os olhos apenas ao estímulo doloroso, fala palavras inapropriadas e localiza a dor. Pela Escala de Coma de Glasgow, sem considerar a reatividade pupilar, sua pontuação é", "opcoes": ["9.", "10.", "8.", "11.", "12."], "gabarito": 1, "explicacao": "Abertura ocular à dor = 2. Palavras inapropriadas = 3. Localiza a dor = 5. Total: 2 + 3 + 5 = 10."}, {"materia": "enf", "texto_base": "", "enunciado": "Durante uma parada cardiorrespiratória, o desfibrilador externo automático (DEA) chega ao local. A conduta correta é", "opcoes": ["usar o DEA apenas se o paciente ainda estiver respirando.", "esperar o fim do ciclo de 5 minutos de RCP antes de usar o DEA.", "checar o pulso por 1 minuto após cada choque antes de voltar a comprimir o tórax.", "ligar o DEA, seguir as instruções e retomar as compressões logo após o choque.", "manter as mãos sobre o paciente durante a análise do ritmo."], "gabarito": 3, "explicacao": "O DEA deve ser usado assim que chegar. Ninguém toca o paciente durante a análise e o choque, e as compressões são retomadas imediatamente após o choque."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente diabético em uso de insulina apresenta sudorese fria, tremores, palpitações e confusão mental antes do almoço. A principal suspeita é", "opcoes": ["hiperglicemia hiperosmolar.", "desidratação leve.", "hipoglicemia.", "cetoacidose diabética.", "crise hipertensiva."], "gabarito": 2, "explicacao": "Sudorese, tremor, taquicardia e confusão são sinais típicos da hipoglicemia, comum em quem usa insulina e atrasa ou pula refeições. Confirma-se com glicemia capilar."}, {"materia": "enf", "texto_base": "", "enunciado": "Na passagem de sonda nasogástrica em adulto, o comprimento a ser introduzido é medido", "opcoes": ["da ponta do nariz até o ombro do mesmo lado.", "da ponta do nariz ao lóbulo da orelha e daí até o apêndice xifoide.", "da boca até o umbigo, em linha reta.", "do lóbulo da orelha até a cicatriz umbilical, com o paciente em decúbito dorsal.", "do queixo até o apêndice xifoide."], "gabarito": 1, "explicacao": "A medida clássica vai da ponta do nariz ao lóbulo da orelha e deste ao apêndice xifoide. Ela aproxima a distância até o estômago."}, {"materia": "enf", "texto_base": "", "enunciado": "Sobre o cateterismo vesical de demora, é correto afirmar que", "opcoes": ["pode ser feito com técnica limpa, já que a uretra não é estéril, dispensando luvas estéreis.", "dispensa a higiene íntima prévia do paciente.", "é procedimento estéril, e o balão só é insuflado após o retorno de urina.", "a bolsa coletora deve ficar acima do nível da bexiga.", "o balão deve ser insuflado antes de a sonda chegar à bexiga."], "gabarito": 2, "explicacao": "A sondagem vesical usa técnica asséptica. Insuflar o balão antes do retorno de urina pode lesar a uretra. A bolsa fica abaixo da bexiga para evitar refluxo."}, {"materia": "enf", "texto_base": "", "enunciado": "Um paciente com insuficiência cardíaca apresenta dispneia intensa ao deitar. Para facilitar a respiração, a posição mais indicada é a de", "opcoes": ["decúbito ventral.", "decúbito dorsal horizontal.", "Fowler.", "Trendelenburg.", "litotomia."], "gabarito": 2, "explicacao": "Na posição de Fowler, com a cabeceira elevada (em geral de 45° a 60°), o diafragma desce e a expansão pulmonar melhora. No Trendelenburg, a cabeça fica abaixo dos pés."}, {"materia": "enf", "texto_base": "", "enunciado": "Segundo o Ministério da Saúde, a primeira consulta de pré-natal deve ocorrer, idealmente,", "opcoes": ["até a 12ª semana de gestação.", "somente após o primeiro ultrassom morfológico.", "entre a 20ª e a 24ª semana.", "no terceiro trimestre.", "depois do quarto mês, quando o bebê se mexe."], "gabarito": 0, "explicacao": "A captação precoce da gestante, com início do pré-natal até a 12ª semana, permite solicitar exames, iniciar suplementação e identificar riscos a tempo."}, {"materia": "enf", "texto_base": "", "enunciado": "Segundo o Ministério da Saúde, a recomendação sobre aleitamento materno é", "opcoes": ["aleitamento exclusivo até 1 ano, sem nenhum outro alimento.", "oferecer chás e água desde o primeiro mês, nos dias quentes.", "aleitamento exclusivo até os 6 meses e complementado até 2 anos ou mais.", "aleitamento exclusivo até os 4 meses e complementado até 1 ano.", "aleitamento exclusivo até os 6 meses, com desmame obrigatório aos 12 meses de idade."], "gabarito": 2, "explicacao": "O Ministério da Saúde e a OMS recomendam leite materno exclusivo até os 6 meses, sem água nem chás, e mantido com alimentos complementares até 2 anos ou mais."}, {"materia": "enf", "texto_base": "", "enunciado": "A coleta do teste do pezinho (triagem neonatal biológica) deve ser feita, idealmente,", "opcoes": ["nas primeiras 12 horas de vida.", "somente se houver histórico familiar de doença.", "aos 2 meses, junto com as vacinas.", "entre o 3º e o 5º dia de vida do bebê.", "no primeiro mês de vida, em qualquer dia."], "gabarito": 3, "explicacao": "O ideal é colher entre o 3º e o 5º dia de vida, depois de o bebê ter mamado, para que os resultados sejam confiáveis e o tratamento comece cedo."}, {"materia": "enf", "texto_base": "", "enunciado": "Logo após receber um antibiótico, um paciente apresenta urticária generalizada, edema de glote, broncoespasmo e queda da pressão arterial. A medicação de primeira escolha nesse quadro é", "opcoes": ["diurético por via endovenosa.", "dipirona por via endovenosa.", "corticoide inalatório.", "anti-histamínico por via oral, em dose dobrada.", "adrenalina por via intramuscular."], "gabarito": 4, "explicacao": "O quadro é de anafilaxia. A adrenalina intramuscular (no vasto lateral da coxa) é o tratamento de primeira escolha. Anti-histamínicos e corticoides são complementares."}, {"materia": "enf", "texto_base": "", "enunciado": "Pelo Código de Ética dos Profissionais de Enfermagem (Resolução Cofen 564/2017), é direito do profissional", "opcoes": ["executar prescrição médica ilegível, desde que registre o fato.", "abandonar o plantão quando não houver substituto disponível.", "administrar medicamento sem conhecer a ação da droga.", "recusar atividades que não sejam de sua competência ou que não ofereçam segurança.", "divulgar informações e fotos do paciente em redes sociais, desde que não mostre o rosto dele."], "gabarito": 3, "explicacao": "O Código de Ética garante ao profissional o direito de recusar atividades que não sejam de sua competência técnica, científica, ética e legal ou que não ofereçam segurança ao profissional, à pessoa ou à coletividade."}, {"materia": "enf", "texto_base": "", "enunciado": "Sobre os registros de enfermagem no prontuário, é correto afirmar que", "opcoes": ["a anotação de enfermagem é privativa do enfermeiro.", "os registros podem ser feitos no fim do plantão, de memória, sem anotar o horário de cada cuidado.", "é permitido usar corretivo para apagar erros de registro.", "os registros podem ser feitos a lápis, para permitir correções.", "a evolução é privativa do enfermeiro, e a anotação cabe a toda a equipe."], "gabarito": 4, "explicacao": "A evolução de enfermagem, que analisa as respostas do paciente, é privativa do enfermeiro. A anotação dos cuidados prestados é feita por toda a equipe, à caneta, com data, horário e identificação, sem rasuras nem corretivo."}, {"materia": "med", "texto_base": "", "enunciado": "Um paciente chega ao pronto-socorro com infarto agudo do miocárdio com supradesnivelamento do segmento ST. Em serviço com hemodinâmica disponível, a estratégia de reperfusão preferencial é", "opcoes": ["cirurgia de revascularização miocárdica imediata em todos os casos.", "angioplastia primária, idealmente em até 90 minutos da chegada.", "apenas analgesia e repouso, sem reperfusão.", "trombólise química após 24 horas de observação.", "aguardar o resultado da troponina para decidir."], "gabarito": 1, "explicacao": "No IAM com supra de ST, a angioplastia primária é a reperfusão preferencial quando há hemodinâmica disponível, com meta de porta-balão de até 90 minutos. O ECG basta para indicar reperfusão, sem esperar a troponina."}, {"materia": "med", "texto_base": "", "enunciado": "No acidente vascular cerebral isquêmico, a trombólise endovenosa com alteplase pode ser indicada, em regra, até", "opcoes": ["4,5 horas do início dos sintomas.", "30 minutos do início dos sintomas.", "12 horas do início dos sintomas.", "48 horas, desde que a tomografia seja normal.", "24 horas do início dos sintomas."], "gabarito": 0, "explicacao": "A janela habitual para a trombólise endovenosa no AVC isquêmico é de até 4,5 horas do início dos sintomas, após a tomografia afastar hemorragia."}, {"materia": "med", "texto_base": "", "enunciado": "São sinais de alarme na dengue, EXCETO:", "opcoes": ["sangramento de mucosas.", "vômitos persistentes.", "febre alta nos primeiros dias da doença.", "hipotensão postural.", "dor abdominal intensa e contínua, referida ou à palpação."], "gabarito": 2, "explicacao": "Febre alta é típica da fase febril e não é sinal de alarme. Dor abdominal intensa, vômitos persistentes, sangramento de mucosas, hipotensão postural, letargia e aumento do hematócrito indicam risco de agravamento."}, {"materia": "med", "texto_base": "", "enunciado": "Pelos critérios usuais, confirma o diagnóstico de diabetes mellitus em adulto", "opcoes": ["glicemia de jejum entre 100 e 125 mg/dL.", "hemoglobina glicada de 5,5%.", "glicemia de jejum igual ou superior a 126 mg/dL em duas ocasiões.", "glicemia de jejum de 100 mg/dL em uma única medida, sem sintomas.", "glicemia casual de 140 mg/dL sem sintomas."], "gabarito": 2, "explicacao": "Glicemia de jejum ≥ 126 mg/dL, confirmada, define diabetes. Também valem HbA1c ≥ 6,5% ou glicemia casual ≥ 200 mg/dL com sintomas. Valores de 100 a 125 mg/dL indicam pré-diabetes."}, {"materia": "med", "texto_base": "", "enunciado": "Pela Diretriz Brasileira de Hipertensão Arterial (2020), considera-se hipertensão arterial, em medidas de consultório, a pressão", "opcoes": ["sistólica ≥ 160 mmHg, apenas.", "sistólica ≥ 140 mmHg e/ou diastólica ≥ 90 mmHg.", "sistólica ≥ 120 mmHg e diastólica ≥ 80 mmHg, em uma medida.", "sistólica ≥ 130 mmHg e diastólica ≥ 85 mmHg.", "diastólica ≥ 100 mmHg, apenas."], "gabarito": 1, "explicacao": "A diretriz de 2020 define HA por PAS ≥ 140 e/ou PAD ≥ 90 mmHg em medidas repetidas de consultório. Valores de 130–139/85–89 são pré-hipertensão."}, {"materia": "med", "texto_base": "", "enunciado": "O esquema básico de tratamento da tuberculose pulmonar em adultos no Brasil dura", "opcoes": ["2 meses, com rifampicina isolada.", "9 meses: 3 de RHZE e 6 de RH, para todos os casos.", "6 meses: 2 meses de RHZE e 4 meses de RH.", "12 meses, com isoniazida isolada.", "3 meses, com dose semanal única."], "gabarito": 2, "explicacao": "O esquema básico tem fase intensiva de 2 meses com rifampicina, isoniazida, pirazinamida e etambutol (RHZE) e fase de manutenção de 4 meses com rifampicina e isoniazida (RH)."}, {"materia": "med", "texto_base": "", "enunciado": "Pela classificação operacional da hanseníase usada no SUS, um paciente com 7 lesões de pele é classificado como", "opcoes": ["paucibacilar, por ter menos de 10 lesões.", "indeterminado, até a biópsia.", "multibacilar apenas se houver nervo espessado.", "multibacilar, por ter mais de 5 lesões.", "paucibacilar, se a baciloscopia for negativa."], "gabarito": 3, "explicacao": "Até 5 lesões de pele indica paucibacilar. Mais de 5 lesões indica multibacilar. A baciloscopia positiva também classifica como multibacilar, mas a negativa não exclui essa forma."}, {"materia": "fisio", "texto_base": "", "enunciado": "Logo após uma entorse aguda de tornozelo, o fisioterapeuta aplica crioterapia. Os principais efeitos esperados são", "opcoes": ["vasodilatação e aumento do fluxo sanguíneo e do metabolismo local.", "vasoconstrição, redução da dor e controle do edema.", "relaxamento muscular por aquecimento profundo.", "aumento da extensibilidade do colágeno.", "aumento do metabolismo e da inflamação local."], "gabarito": 1, "explicacao": "Na fase aguda, o frio causa vasoconstrição, reduz o metabolismo local, a dor e a formação de edema. Aquecimento e vasodilatação são efeitos do calor, indicados em fases posteriores."}, {"materia": "fisio", "texto_base": "", "enunciado": "A estimulação elétrica nervosa transcutânea (TENS) é usada principalmente para", "opcoes": ["redução de edema linfático crônico.", "consolidação de fraturas expostas.", "aumento da força de preensão em pacientes com lesão nervosa total.", "fortalecimento muscular por hipertrofia.", "analgesia, com base na teoria das comportas da dor."], "gabarito": 4, "explicacao": "A TENS é um recurso de eletroanalgesia. Sua ação é explicada em parte pela teoria das comportas (Melzack e Wall) e pela liberação de opioides endógenos."}, {"materia": "fisio", "texto_base": "", "enunciado": "No pós-operatório de cirurgia abdominal alta, o uso do incentivador inspiratório tem como principal objetivo", "opcoes": ["promover a expansão pulmonar e prevenir atelectasias.", "reduzir a frequência cardíaca de repouso.", "substituir a deambulação precoce e a mobilização no leito do paciente.", "aumentar a produção de secreção brônquica.", "fortalecer a musculatura abdominal operada."], "gabarito": 0, "explicacao": "O incentivador inspiratório estimula inspirações lentas e profundas, que favorecem a expansão pulmonar e previnem atelectasias, comuns após cirurgias abdominais altas e torácicas."}, {"materia": "fisio", "texto_base": "", "enunciado": "Um paciente com sequela de AVC apresenta resistência ao movimento passivo que aumenta com a velocidade do estiramento e cede de repente (sinal do canivete). Esse quadro caracteriza", "opcoes": ["ataxia cerebelar.", "flacidez, por lesão do neurônio motor inferior.", "espasticidade, por lesão do neurônio motor superior.", "contratura articular fixa.", "rigidez em roda denteada, típica da doença de Parkinson."], "gabarito": 2, "explicacao": "Espasticidade é hipertonia dependente da velocidade, com sinal do canivete, típica da lesão do neurônio motor superior (AVC). A rigidez parkinsoniana não depende da velocidade e lembra roda denteada."}, {"materia": "pcd", "texto_base": "", "enunciado": "Uma mulher com síndrome de Down, de 25 anos, deseja se casar. Pelo Estatuto da Pessoa com Deficiência (Lei 13.146/2015), ela", "opcoes": ["precisa de autorização judicial para se casar.", "é absolutamente incapaz e não pode se casar.", "depende da autorização dos pais e do Ministério Público, qualquer que seja a idade.", "pode se casar, pois a deficiência não afeta a plena capacidade civil.", "só pode se casar com a assistência de um curador."], "gabarito": 3, "explicacao": "O art. 6º do Estatuto diz que a deficiência não afeta a plena capacidade civil da pessoa, inclusive para casar-se e constituir união estável."}, {"materia": "igual", "texto_base": "", "enunciado": "Durante o atendimento, um paciente ofende uma técnica de enfermagem com xingamentos referentes à cor da pele dela. Após a Lei 14.532/2023, essa conduta configura", "opcoes": ["contravenção penal de preconceito, punida só com multa.", "injúria racial de ação penal privada, prescritível em 2 anos, com pena de detenção.", "mera infração ética, sem repercussão penal.", "injúria racial, equiparada ao racismo, com pena de reclusão de 2 a 5 anos.", "injúria simples, com pena de detenção de 1 a 6 meses."], "gabarito": 3, "explicacao": "A Lei 14.532/2023 levou a injúria racial para a Lei 7.716/1989 (art. 2º-A), com pena de 2 a 5 anos de reclusão. Como o racismo, ela é inafiançável e imprescritível."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('saude', date '2026-11-15', 'Simulado 2 · Saúde', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'saude' and s.data = date '2026-11-15' group by s.id;
